import importlib.util, json, os, re, signal, statistics, subprocess, sys
from pathlib import Path
base = Path(__file__).resolve().parent
root = Path('/home/koishi/.config/nvim')
spec = importlib.util.spec_from_file_location('benchmark', root / 'scripts/benchmark.py')
benchmark = importlib.util.module_from_spec(spec)
spec.loader.exec_module(benchmark)
small = base / 'small.lua'
small.write_text('local answer = 42\nprint(answer)\n')
scenes = {'empty':None, 'small_lua':small, 'python':Path('/home/koishi/Projects/transformer/transformer.py')}
results = {}
for scene, sample in scenes.items():
    targets = ['baseline', 'no_predicates', 'native_gc', 'lazy_faster']
    values = {name: [] for name in targets}
    for index in range(7):
        order = targets[index % len(targets):] + targets[:index % len(targets)]
        if index % 2:
            order.reverse()
        for name in order:
            run = base / 'startup' / scene / name / str(index)
            values[name].append(benchmark.measure('nvim', base/name, run, base/'startup'/scene/name/'cache', sample))
    results[scene] = {name:{'runs_ms':runs, 'median_ms':statistics.median(runs[1:]), 'paired_delta_ms':statistics.median([a-b for a,b in zip(runs[1:],values['baseline'][1:])])} for name,runs in values.items()}
    print(scene, json.dumps(results[scene]), flush=True)
(base/'startup-results.json').write_text(json.dumps(results,indent=2)+'\n')
for scene, sample in scenes.items():
    run = base/'profile'/scene
    (run/'config').mkdir(parents=True)
    (run/'config/nvim').symlink_to(base/'baseline')
    env = os.environ | {'XDG_CONFIG_HOME':str(run/'config'), 'XDG_CACHE_HOME':str(base/'startup'/scene/'baseline'/'cache'), 'XDG_STATE_HOME':str(run/'state'), 'NVIM_LOG_FILE':str(run/'nvim.log'), 'NVIM_CHECK_ONLY':'1', 'NVIM_APPNAME':'nvim', 'NVIM_COST_OUTPUT':str(run/'cost.json')}
    cmd = ['nvim','--headless','-u',str(base/'baseline/init.lua'),'-i','NONE','--startuptime',str(run/'startup.log'),'--cmd', 'lua dofile('+json.dumps(str(base/'probe.lua'))+')','--cmd','autocmd VimEnter * lua vim.defer_fn(function() vim.cmd("qa!") end, 200)']
    if sample: cmd.append(str(sample))
    with (run/'output.log').open('w') as output:
        result = subprocess.run(cmd,env=env,stdout=output,stderr=output,cwd=base/'baseline',timeout=30)
    assert result.returncode == 0, str(run)
    print('setup profile', scene, (run/'cost.json').read_text().strip(), flush=True)
